:root {
  color-scheme: light;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #17211f;
  background: #f3f6f4;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
}

.dashboard {
  width: min(100% - 40px, 960px);
  margin: 0 auto;
  padding: 64px 0 80px;
}

.dashboard-header {
  margin-bottom: 32px;
}

.eyebrow {
  margin: 0 0 8px;
  color: #55736a;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 10px;
  font-size: clamp(2rem, 5vw, 3rem);
  letter-spacing: -0.04em;
}

h2 {
  margin-bottom: 0;
  font-size: 1.25rem;
  letter-spacing: -0.02em;
}

.intro {
  margin-bottom: 0;
  color: #5d6d67;
  font-size: 1rem;
}

.dashboard-card {
  margin-top: 18px;
  padding: 24px;
  border: 1px solid #dce5df;
  border-radius: 18px;
  background: #fff;
  box-shadow: 0 10px 30px rgb(29 54 44 / 4%);
}

.section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 24px;
}

.status-indicator {
  padding: 7px 10px;
  border-radius: 999px;
  background: #e8f4ec;
  color: #316146;
  font-size: 0.75rem;
  font-weight: 650;
  white-space: nowrap;
}

.status-indicator.private {
  background: #eef1fb;
  color: #4e5c91;
}

.project-totals,
.member-details {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin: 0;
}

.project-totals > div,
.member-details > div {
  min-width: 0;
  padding: 16px;
  border-radius: 12px;
  background: #f6f8f6;
}

.project-totals dt,
.member-details dt,
.detail-label {
  display: block;
  margin-bottom: 8px;
  color: #687871;
  font-size: 0.8rem;
  font-weight: 600;
}

.project-totals dd,
.member-details dd,
.detail-placeholder {
  display: block;
  margin: 0;
  overflow-wrap: anywhere;
  color: #17211f;
  font-size: 1rem;
  font-weight: 650;
}

.project-totals dd {
  font-size: 1.75rem;
  letter-spacing: -0.04em;
}

.detail-placeholder {
  color: #819089;
  font-weight: 500;
}

@media (max-width: 560px) {
  .dashboard {
    width: min(100% - 28px, 960px);
    padding-top: 40px;
  }

  .dashboard-card {
    padding: 18px;
  }

  .section-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
  }

  .project-totals,
  .member-details {
    grid-template-columns: 1fr;
  }
}
